<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import { useAuthStore } from '../../stores/auth'

type Mode='hub'|'items'|'favorites'|'subscriptions'|'settings'
const props=defineProps<{mode:Mode}>();const auth=useAuthStore()
type User={id:number;username:string;display_name:string;email:string;role:string;account_status:string;phone:string;notification_preferences:Record<string,boolean>;created_at:string}
type Item={id:string;title:string;kind:string;review_status:string;business_status:string;updated_at:string;allowed_actions:string[]}
type Favorite={id:number;item:{id:string;title:string;kind:string;category_name:string;location_name:string;business_status:string;occurred_at:string}}
type Subscription={id:number;name:string;criteria:Record<string,string>;minimum_score:string;is_active:boolean;created_at:string}
const user=ref<User|null>(null);const items=ref<Item[]>([]);const favorites=ref<Favorite[]>([]);const subscriptions=ref<Subscription[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const success=ref('')
const settings=reactive({email:'',phone:'',match_notifications:true,claim_notifications:true})
const newSubscription=reactive({name:'',keyword:'',kind:'FOUND',minimum_score:'0.65'})
const actionBusy=ref('')
const title=computed(()=>({hub:'个人中心',items:'我的发布',favorites:'我的收藏',subscriptions:'线索订阅',settings:'账户设置'}[props.mode]))
async function load(){loading.value=true;error.value='';try{const me=await api<{data:User}>('/auth/me/');user.value=me.data;Object.assign(settings,{email:me.data.email,phone:me.data.phone||'',match_notifications:me.data.notification_preferences?.match!==false,claim_notifications:me.data.notification_preferences?.claim!==false});if(['hub','items'].includes(props.mode)){const response=await api<{data:{items:Item[]}}>('/items/?mine=true&page_size=100');items.value=response.data.items}if(['hub','favorites'].includes(props.mode)){const response=await api<{data:{items:Favorite[]}}>('/items/favorites/?page_size=100');favorites.value=response.data.items}if(['hub','subscriptions'].includes(props.mode)){const response=await api<{data:{items:Subscription[]}}>('/items/subscriptions/?page_size=100');subscriptions.value=response.data.items}}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取个人数据'}finally{loading.value=false}}
async function saveSettings(){busy.value=true;error.value='';success.value='';try{const response=await api<{data:User}>('/auth/me/',{method:'PATCH',body:JSON.stringify({email:settings.email,phone:settings.phone,notification_preferences:{match:settings.match_notifications,claim:settings.claim_notifications}})});user.value=response.data;await auth.bootstrap();success.value='设置已保存'}catch(reason){error.value=reason instanceof ApiError?reason.message:'保存失败'}finally{busy.value=false}}
async function createSubscription(){busy.value=true;error.value='';try{await api('/items/subscriptions/',{method:'POST',body:JSON.stringify({name:newSubscription.name,criteria:{q:newSubscription.keyword,kind:newSubscription.kind},minimum_score:newSubscription.minimum_score,is_active:true})});Object.assign(newSubscription,{name:'',keyword:'',kind:'FOUND',minimum_score:'0.65'});await load()}catch(reason){error.value=reason instanceof ApiError?reason.message:'创建订阅失败'}finally{busy.value=false}}
async function removeFavorite(id:number){await api(`/items/favorites/${id}/`,{method:'DELETE'});favorites.value=favorites.value.filter(entry=>entry.id!==id)}
async function toggleSubscription(entry:Subscription){await api(`/items/subscriptions/${entry.id}/`,{method:'PATCH',body:JSON.stringify({is_active:!entry.is_active})});await load()}
async function manageItem(item:Item,action:'submit'|'withdraw'|'close'|'delete'){
  const prompts={submit:'确认将这条信息提交审核吗？',withdraw:'确认撤回待审核信息并恢复为草稿吗？',close:'确认关闭这条公开线索吗？关闭后将不再参与公开匹配。',delete:'确认永久删除这条未公开草稿吗？此操作不可撤销。'}
  if(!window.confirm(prompts[action]))return
  actionBusy.value=`${item.id}:${action}`;error.value='';success.value=''
  try{
    if(action==='delete')await api(`/items/${item.id}/`,{method:'DELETE'})
    else await api(`/items/${item.id}/${action}/`,{method:'POST'})
    success.value=action==='delete'?'草稿已删除':action==='withdraw'?'已撤回为草稿':action==='close'?'线索已关闭':'已提交审核'
    await load()
  }catch(reason){error.value=reason instanceof ApiError?reason.message:'操作失败，请稍后重试'}finally{actionBusy.value=''}
}
onMounted(load);watch(()=>props.mode,load)
</script>
<template><div class="page account"><header><h1 class="page-title">{{title}}</h1></header><nav class="account-nav"><RouterLink to="/me">概览</RouterLink><RouterLink to="/me/items">我的发布</RouterLink><RouterLink to="/me/favorites">收藏</RouterLink><RouterLink to="/me/subscriptions">订阅</RouterLink><RouterLink to="/me/settings">设置</RouterLink></nav><p v-if="loading" class="empty">正在读取账户数据…</p><p v-else-if="error&&!user" class="empty error">{{error}}</p><template v-else-if="user"><p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p><section v-if="mode==='hub'" class="hub"><article class="panel profile"><span class="avatar"><AppIcon name="user"/></span><div><p class="eyebrow">{{user.role}}</p><h2>{{user.username}}</h2><p>{{user.account_status}}</p></div><RouterLink class="button button-ghost" to="/me/settings">编辑资料</RouterLink></article><div class="stats"><RouterLink to="/me/items"><strong>{{items.length}}</strong><span>发布记录</span></RouterLink><RouterLink to="/me/favorites"><strong>{{favorites.length}}</strong><span>收藏线索</span></RouterLink><RouterLink to="/me/subscriptions"><strong>{{subscriptions.filter(entry=>entry.is_active).length}}</strong><span>启用订阅</span></RouterLink></div><section class="panel next"><h2>安全待办</h2><ul><li><AppIcon name="shield"/><span>公开描述中不填写联系方式或完整证件号。</span></li><li><AppIcon name="map"/><span>交接必须在授权服务站完成限次码和双方确认。</span></li></ul></section></section><section v-else-if="mode==='items'" class="list"><article v-for="item in items" :key="item.id" class="panel row"><span>{{item.kind==='LOST'?'遗失':'招领'}}</span><div><RouterLink :to="`/items/${item.id}`"><strong>{{item.title}}</strong></RouterLink><small>{{new Date(item.updated_at).toLocaleString('zh-CN')}}</small></div><span class="status-tag">{{item.review_status}} / {{item.business_status}}</span><div class="row-actions"><RouterLink class="link-button" :to="`/items/${item.id}`">查看</RouterLink><RouterLink v-if="item.allowed_actions.includes('edit')" class="link-button" :to="`/items/${item.id}/edit`">编辑</RouterLink><button v-if="item.allowed_actions.includes('submit')" class="link-button" :disabled="Boolean(actionBusy)" @click="manageItem(item,'submit')">提交</button><button v-if="item.allowed_actions.includes('withdraw')" class="link-button" :disabled="Boolean(actionBusy)" @click="manageItem(item,'withdraw')">撤回</button><button v-if="item.allowed_actions.includes('close')" class="link-button" :disabled="Boolean(actionBusy)" @click="manageItem(item,'close')">关闭</button><button v-if="item.allowed_actions.includes('delete')" class="link-button danger" :disabled="Boolean(actionBusy)" @click="manageItem(item,'delete')">删除</button></div></article><p v-if="!items.length" class="empty">尚无发布记录。</p></section><section v-else-if="mode==='favorites'" class="list"><article v-for="entry in favorites" :key="entry.id" class="panel row"><span>{{entry.item.kind==='LOST'?'遗失':'招领'}}</span><div><RouterLink :to="`/items/${entry.item.id}`"><strong>{{entry.item.title}}</strong></RouterLink><small>{{entry.item.category_name}} · {{entry.item.location_name}}</small></div><span class="status-tag">{{entry.item.business_status}}</span><button class="link-button" @click="removeFavorite(entry.id)">取消收藏</button></article><p v-if="!favorites.length" class="empty">尚无收藏线索。</p></section><section v-else-if="mode==='subscriptions'" class="subscription-layout"><form class="panel create" @submit.prevent="createSubscription"><h2>新建线索订阅</h2><label><span>订阅名称</span><input v-model="newSubscription.name" required/></label><label><span>关键词</span><input v-model="newSubscription.keyword" required/></label><label><span>目标类型</span><select v-model="newSubscription.kind"><option value="FOUND">招领</option><option value="LOST">遗失</option></select></label><label><span>最低分数（0–1）</span><input v-model="newSubscription.minimum_score" type="number" min="0" max="1" step="0.01" required/></label><button class="button button-brand" :disabled="busy">创建订阅</button></form><div class="list"><article v-for="entry in subscriptions" :key="entry.id" class="panel subscription"><div><span class="status-tag">{{entry.is_active?'已启用':'已暂停'}}</span><h2>{{entry.name}}</h2><p>{{entry.criteria}} · 最低 {{entry.minimum_score}}</p></div><button class="button button-ghost" @click="toggleSubscription(entry)">{{entry.is_active?'暂停':'启用'}}</button></article><p v-if="!subscriptions.length" class="empty">尚无订阅。</p></div></section><form v-else class="panel settings" @submit.prevent="saveSettings"><h2>账户与通知偏好</h2><label><span>用户名（不可修改）</span><input :value="user.username" disabled/></label><label><span>邮箱</span><input v-model="settings.email" type="email"/></label><label><span>手机号（仅授权流程使用）</span><input v-model="settings.phone"/></label><label class="check"><input v-model="settings.match_notifications" type="checkbox"/>接收匹配通知</label><label class="check"><input v-model="settings.claim_notifications" type="checkbox"/>接收认领与交接通知</label><footer><button class="button button-brand" :disabled="busy">保存设置</button></footer></form></template></div></template>
<style scoped>.account-nav{display:flex;gap:6px;overflow:auto;margin:30px 0 24px}.account-nav a{padding:10px 14px;color:var(--ct-text-muted);border:1px solid var(--ct-border);border-radius:10px;white-space:nowrap}.account-nav a.router-link-exact-active{color:var(--ct-brand-ink);background:var(--ct-brand)}.hub{display:grid;grid-template-columns:1fr 360px;gap:16px}.profile{grid-column:1/-1;display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;padding:25px}.avatar{display:grid;place-items:center;width:62px;aspect-ratio:1;color:var(--ct-brand);border-radius:18px;background:rgba(141,48,46,.08);font-size:30px}.profile h2,.profile p{margin:3px 0}.profile>div>p:last-child{color:var(--ct-text-muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stats a{padding:24px;border:1px solid var(--ct-border);border-radius:14px;background:var(--ct-surface)}.stats strong,.stats span{display:block}.stats strong{color:var(--ct-brand);font-size:32px}.stats span{margin-top:8px;color:var(--ct-text-muted)}.next{padding:24px;grid-row:2/4;grid-column:2}.next h2{margin:9px 0}.next ul{display:grid;gap:17px;padding:0;list-style:none}.next li{display:flex;gap:9px;color:var(--ct-text-muted);line-height:1.55}.next svg{flex:0 0 auto;color:var(--ct-success)}.list{display:grid;gap:10px}.row{display:grid;grid-template-columns:auto minmax(180px,1fr) auto auto;gap:16px;align-items:center;padding:18px;box-shadow:none}.row>span:first-child{color:var(--ct-brand)}.row small{display:block;margin-top:5px;color:var(--ct-text-muted)}.row-actions{display:flex;justify-content:flex-end;gap:6px;flex-wrap:wrap}.link-button{padding:6px 8px;color:var(--ct-brand);border:0;border-radius:6px;background:transparent;cursor:pointer}.link-button:hover{background:var(--ct-bg-soft)}.link-button.danger{color:var(--ct-danger)}.subscription-layout{display:grid;grid-template-columns:340px 1fr;gap:16px}.create,.settings{display:grid;gap:16px;padding:26px;box-shadow:none}.create h2,.settings h2{margin:0 0 8px}.create label span,.settings label span{display:block;margin-bottom:7px;color:var(--ct-text-muted);font-size:11px}.create input,.create select,.settings input{width:100%;padding:12px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:10px;background:var(--ct-bg-soft)}.subscription{display:flex;justify-content:space-between;align-items:center;padding:20px;box-shadow:none}.subscription h2{margin:10px 0 5px}.subscription p{color:var(--ct-text-muted)}.settings{max-width:700px}.settings .check{display:flex;gap:10px;color:var(--ct-text-muted)}.settings .check input{width:auto}.settings footer{display:flex;justify-content:flex-end}.empty{display:grid;place-items:center;min-height:240px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:15px}.notice{padding:12px;border-radius:10px}.error{color:var(--ct-danger);background:rgba(173,52,52,.07)}.success{color:var(--ct-success);background:rgba(54,100,75,.07)}@media(max-width:850px){.hub,.subscription-layout{grid-template-columns:1fr}.next{grid-row:auto;grid-column:auto}.stats{grid-template-columns:1fr 1fr 1fr}.row{grid-template-columns:auto 1fr}.row>.status-tag,.row>.row-actions{grid-column:2}.row-actions{justify-content:flex-start}}@media(max-width:600px){.profile{grid-template-columns:auto 1fr}.profile>.button{grid-column:2}.stats{grid-template-columns:1fr}}</style>
